<?php
require 'config.php';
$dari=trim($_GET['dari']??'');$sampai=trim($_GET['sampai']??'');$status=trim($_GET['status']??'');$q=trim($_GET['q']??'');$statuses=['pending','diproses','dikirim','selesai','dibatalkan'];if(!in_array($status,$statuses,true))$status='';
$where=[];$params=[];if($dari!==''){$where[]='t.tanggal >= ?';$params[]=$dari;}if($sampai!==''){$where[]='t.tanggal <= ?';$params[]=$sampai;}if($status!==''){$where[]='t.status_pesanan = ?';$params[]=$status;}if($q!==''){$where[]='(CAST(t.id_transaksi AS CHAR) LIKE ? OR p.nama LIKE ?)';$params[]="%$q%";$params[]="%$q%";}$condition=$where?' WHERE '.implode(' AND ',$where):'';$from=' FROM transaksi t INNER JOIN pelanggan p ON p.id_pelanggan=t.id_pelanggan';
$st=$pdo->prepare('SELECT t.id_transaksi,t.tanggal,p.nama nama_pelanggan,t.nama_barang,t.jumlah,t.total subtotal,t.status_pesanan,COALESCE(t.metode_pembayaran,\'tunai\') metode_pembayaran,t.total diterima'.$from.$condition.' ORDER BY t.tanggal DESC,t.id_transaksi DESC');$st->execute($params);$rows=$st->fetchAll();$ss=$pdo->prepare('SELECT COUNT(*) jumlah,COALESCE(SUM(t.total),0) diterima'.$from.$condition);$ss->execute($params);$sum=$ss->fetch();$periode=($dari?:'Awal').' s.d. '.($sampai?:'Hari ini');
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Transaksi Penjualan TokoKu</title><style>@page{size:A4 portrait;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#172033;font-size:11px;line-height:1.25;margin:0}.head{text-align:center;border-bottom:2px solid #172033;padding-bottom:6px;margin-bottom:8px}.head h1{font-size:18px;margin:0 0 4px}.head p{margin:1px 0;color:#4b5563;font-size:10px}.meta{display:flex;justify-content:space-between;margin-bottom:7px;font-size:10px}.meta strong{color:#1d4ed8}table{width:100%;border-collapse:collapse;table-layout:fixed}th{background:#eaf2ff;color:#1e3a8a;font-size:9px;text-transform:uppercase;line-height:1.15}th,td{border:1px solid #cbd5e1;padding:4px 4px;vertical-align:middle;word-wrap:break-word}td.num{text-align:right;white-space:nowrap}tbody tr:nth-child(even){background:#f8fafc}.summary{margin-top:7px;margin-left:auto;width:65%}.summary td{border:0;border-bottom:1px solid #e2e8f0;padding:3px}.summary td:last-child{text-align:right;font-weight:bold}.summary .grand td{border-top:2px solid #172033;border-bottom:0;font-size:12px;padding-top:5px}.signature{margin-top:12px;text-align:right;color:#64748b;font-size:10px}@media print{tr{page-break-inside:avoid}thead{display:table-header-group}}</style></head><body><header class="head"><h1>LAPORAN TRANSAKSI PENJUALAN TOKOKU</h1><p>Periode laporan: <?=e($periode)?></p><p>Tanggal cetak: <?=e(date('d M Y H:i'))?></p></header><div class="meta"><span>Status: <strong><?=e($status?ucfirst($status):'Semua status')?></strong></span><span><?=e($sum['jumlah'])?> transaksi</span></div><table><thead><tr><th style="width:4%">No.</th><th style="width:8%">ID</th><th style="width:10%">Tanggal</th><th style="width:14%">Pembeli</th><th style="width:20%">Produk &amp; Qty</th><th style="width:14%">Subtotal Produk</th><th style="width:14%">Diterima Penjual</th><th style="width:9%">Status</th><th style="width:7%">Pembayaran</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr><td><?=$i+1?></td><td>#<?=e($r['id_transaksi'])?></td><td><?=e(date('d/m/Y',strtotime($r['tanggal'])))?></td><td><?=e($r['nama_pelanggan'])?></td><td><?=e($r['nama_barang'])?> × <?=e($r['jumlah'])?></td><td class="num"><?=rupiah($r['subtotal'])?></td><td class="num"><strong><?=rupiah($r['diterima'])?></strong></td><td><?=e(ucfirst($r['status_pesanan']))?></td><td><?=e(strtoupper($r['metode_pembayaran']))?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="9">Tidak ada data transaksi.</td></tr><?php endif; ?></tbody></table><table class="summary"><tr class="grand"><td>Total pendapatan penjual</td><td><?=rupiah($sum['diterima'])?></td></tr></table><div class="signature">Dokumen dicetak dari TokoKu</div><script>window.addEventListener('load',function(){setTimeout(function(){window.print()},250)})</script></body></html>
